	baseEditorsApi.prototype.getFileAsFromChanges = function()
	{
		var func_before = null;
		var func_after = null;
		if (this.editorId === AscCommon.c_oEditorId.Word)
		{
			if (this.WordControl && this.WordControl.m_oLogicDocument && this.WordControl.m_oLogicDocument.IsViewModeInReview())
			{
				var isFinal = (this.WordControl.m_oLogicDocument.ViewModeInReview.mode === 1) ? true : false;

				func_before = function(api) {
					api.WordControl.m_oLogicDocument.Start_SilentMode();
					api.asc_EndViewModeInReview();
				};
				func_after = function(api) {
					api.asc_BeginViewModeInReview(isFinal);
					api.WordControl.m_oLogicDocument.End_SilentMode(false);
				};
			}
		}

		func_before && func_before(this);
		var ret = this.asc_nativeGetFile3();
		func_after && func_after(this);
		return ret;
	};

	baseEditorsApi.prototype.initShortcuts = function(arrShortcuts, isRemoveBeforeAdd)
	{
		// [[ActionType, KeyCode, Ctrl, Shift, Alt]]
		for (var nIndex = 0, nCount = arrShortcuts.length; nIndex < nCount; ++nIndex)
		{
			var s = arrShortcuts[nIndex];

			if (true === isRemoveBeforeAdd)
				this.Shortcuts.RemoveByType(s[0]);

			this.Shortcuts.Add(s[0], s[1], s[2], s[3], s[4], s[5]);
		}
	};
	baseEditorsApi.prototype.initDefaultShortcuts = function()
	{
		if (!this.Shortcuts) {
			return;
		}
		const mapShortcutActions = Asc.c_oAscUnlockedShortcutActionTypes;
		for (let sShortcutAction in mapShortcutActions) {
			const arrShortcuts = Asc.c_oAscDefaultShortcuts[sShortcutAction];
			if (arrShortcuts) {
				for (let i = 0; i < arrShortcuts.length; i += 1) {
					this.Shortcuts.ApplyFromStorage(arrShortcuts[i]);
				}
			}
		}
	};
	baseEditorsApi.prototype.asc_resetAllShortcutTypes = function() {
		if (!this.Shortcuts) {
			return;
		}
		this.Shortcuts.Reset();
		this.initDefaultShortcuts();
	};
	baseEditorsApi.prototype.asc_resetShortcutType = function(nShortcutType) {
		if (!this.Shortcuts) {
			return;
		}
		this.Shortcuts.RemoveByType(nShortcutType);
		const arrDefaultShortcuts = Asc.c_oAscDefaultShortcuts[nShortcutType];
		if (arrDefaultShortcuts) {
			for (let i = 0; i < arrDefaultShortcuts.length; i += 1) {
				this.Shortcuts.ApplyFromStorage(arrDefaultShortcuts[i]);
			}
		}
	};
	baseEditorsApi.prototype.asc_applyAscShortcuts = function(arrAscShortcuts) {
		if (!this.Shortcuts) {
			return;
		}
		for (let i = 0; i < arrAscShortcuts.length; i++) {
			this.Shortcuts.ApplyFromStorage(arrAscShortcuts[i]);
		}
	};
