		if (AscFormat.isRealNumber(nValue))
		{
			const oTabs = new AscCommonWord.CParaTabs();
			oTabs.Add(new AscCommonWord.CParaTab(Asc.c_oAscTabType.Num, nValue));
			oParaPr.Tabs = oTabs;
		}
		else
		{
			delete oParaPr.Tabs;
		}
